const TYPE_LABEL={club:'Club',miembro:'Miembro',competidor:'Competidor',marca:'Marca',federacion:'Federación',profesional:'Profesional / Representante',media:'Media / Creador',espectador:'Espectador'};
const REVIEW_STATES=[['under_review','En revisión'],['needs_information','Solicitar información'],['verified','Verificar'],['limited','Limitar'],['suspended','Suspender'],['rejected','Rechazar']];
