      <section><h4>Identidades conectadas</h4><div class="kx-admin-club-stats"><span>Social <strong>${data.social_profile_id?'Disponible':'Pendiente'}</strong></span><span>Showcase <strong>${data.showcase_provider_id?'Disponible':'Pendiente'}</strong></span></div><div class="row-actions">${data.social_profile_id?`<button class="btn btn-primary btn-sm" id="admin-open-club-public">Ver perfil público</button>`:''}</div></section>
